    "UTC": "Etc/UTC",
    "GMT": "Etc/UTC",
}
_UTC_NAMES = {"Etc/GMT", "Etc/GMT0", "Etc/GMT+0", "Etc/GMT-0", "Etc/Greenwich", "Etc/UCT", "Etc/Universal", "Etc/Zulu",
              "UCT", "Universal", "Zulu", "Greenwich", "GMT0", "GMT+0", "GMT-0"}
_all_links: dict[str, str] | None = None


def _database_links() -> dict[str, str]:
    """Link name -> target from the system tz database source (tzdata.zi), when present."""
    global _all_links
    if _all_links is None:
        links: dict[str, str] = {}
        for base in zoneinfo.TZPATH:
            try:
                with open(os.path.join(base, "tzdata.zi"), encoding="utf-8") as f:
                    for row in f:
                        parts = row.split()
                        if len(parts) == 3 and parts[0] == "L":
                            links[parts[2]] = parts[1]
                break
            except OSError:
                continue
        _all_links = links
    return _all_links


def _canonical_zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\s*([+-])(\d{1,2})(?::?(\d{2}))?", tz)
    if m:
        hours, minutes = int(m.group(2)), int(m.group(3) or 0)
        if minutes:
            raise ValueError(f"unsupported fixed offset {tz!r}: only whole hours exist")
        if hours == 0:
            return "Etc/UTC"
        if hours > (14 if m.group(1) == "+" else 12):
            raise ValueError(f"unsupported fixed offset {tz!r}")
        return f"Etc/GMT{'-' if m.group(1) == '+' else '+'}{hours}"
    if tz in _LINKS:
        return _LINKS[tz]
    if tz in _UTC_NAMES:
        return "Etc/UTC"
    seen = set()
    links = _database_links()
    while tz in links and tz not in seen:
        seen.add(tz)
        tz = links[tz]
        if tz in _UTC_NAMES:
            return "Etc/UTC"
    return tz


_SUPPORTED = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}


def _report_locale(posix: str) -> str:
    name = re.split(r"[.@]", posix.strip(), maxsplit=1)[0]
    parts = [p for p in re.split(r"[-_]", name) if p]
    if not parts:
        return "en-US"
    lang = parts[0].lower()
    region = parts[1].upper() if len(parts) > 1 and len(parts[1]) in (2, 3) else None
    tag = f"{lang}-{region}" if region else lang
    if tag in _SUPPORTED:
        return tag
    if lang in _SUPPORTED:
        return lang
    return "en-US"


def _digits(currency: str) -> int:
    if currency in {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}:
        return 0
    if currency in {"BHD", "JOD", "KWD", "OMR", "TND"}:
        return 3
    return 2


def _round(value: str, digits: int) -> Decimal:
    with localcontext() as ctx:
        ctx.prec = 60
        return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def _group(integer: str, locale: str) -> list[str]:
    if locale == "es" and len(integer) == 4:
        return [integer]
    if locale == "en-IN" and len(integer) > 3:
        head, tail = integer[:-3], integer[-3:]
        groups = []
        while head:
            groups.insert(0, head[-2:])
            head = head[:-2]
        return groups + [tail]
    groups = []
    while integer:
        groups.insert(0, integer[-3:])
        integer = integer[:-3]
    return groups


# locale -> (decimal, group, code goes before)
_STYLE = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True), "en-IN": (".", ",", True),
    "pt-BR": (",", ".", True),
    "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\u2019", False),
    "fr-FR": (",", "\u202f", False),
}


def _text(amount: Decimal, currency: str, locale: str, digits: int) -> str:
    dec, grp, before = _STYLE[locale]
    negative = amount < 0
    whole, _, frac = f"{abs(amount):f}".partition(".")
    number = grp.join(_group(whole, locale))
    if digits:
        number += dec + frac.ljust(digits, "0")[:digits]
    if negative:
        number = "-" + number
    return f"{currency}\u00a0{number}" if before else f"{number}\u00a0{currency}"


def monthly_statement(transport: Transport, merchant: Merchant, year: int, month: int) -> Statement:
    """The statement of `merchant` for one calendar month, with its days in the merchant's time zone.

    One line per day that has settlements, in day order, with the figures and the text the
    Meridale dashboard shows. Raises ApiError when the API answers with an error.
    """
    first = date(year, month, 1)
    after = date(year + month // 12, month % 12 + 1, 1)  # half-open range: the day after the month
    locale = _report_locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _canonical_zone(merchant.tz),
        "from": first.isoformat(),
        "to": after.isoformat(),
        "locale": locale,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    currency = report["currency"]
    digits = _digits(currency)
    lines = []
    for d in report["days"]:
        gross, fees, refunds = (_round(d[k], digits) for k in ("gross", "fees", "refunds"))
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _text(net, currency, locale, digits)))
    total = sum((line.net for line in lines), Decimal(0).scaleb(-digits))
    return Statement(merchant.id, currency, tuple(lines), total, _text(total, currency, locale, digits))
